import{z as t,x as s,o as r,c as d,q as A,j as l,D as E,d as o,s as B,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"掠夺与排他","description":"","frontmatter":{"title":"掠夺与排他","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/predation-exclusion.md","filePath":"econ/predation-exclusion.md","lastUpdated":1791063341000}'),p={name:"econ/predation-exclusion.md"};function c(C,a,h,m,u,f){const n=s("Mermaid");return r(),d("div",null,[a[2]||(a[2]=A('<h1 id="掠夺与排他" tabindex="-1">掠夺与排他 <a class="header-anchor" href="#掠夺与排他" aria-label="Permalink to &quot;掠夺与排他&quot;">​</a></h1><div class="epigraph"><p>低于成本的价格若只在对手退出后才变得最优，那是掠夺；排他合同若把进入的沉没抬到无法覆盖，那是封锁。两者都改市场结构，而不是改一次静态加价。</p><footer>—— McGee, Journal of Law and Economics 1958；Ordover and Willig, Yale Law Journal 1981；Ordover, Saloner and Salop 排他；对照 Tirole 与微观课掠夺性定价</footer></div><p><a href="/econ/merger-simulation">上一课</a>通过改所有权让交叉弹性内部化。本课缺口是不合并也能改变 \\(N\\)：先牺牲、再在更少对手的市场里补偿；或用合同、兼容、渠道把对手的 \\(F\\) 抬高。微观<a href="/econ/predatory-pricing">掠夺性定价</a>已在完全信息、完美资本市场上给出 McGee 式怀疑。产业组织收束课把怀疑接到融资约束、多市场声誉，以及<a href="/econ/vertical-restraints">纵向约束</a>、<a href="/econ/network-standards-io">网络与标准</a>里已经出现的封锁。后课公共财政换题；本课是 IO 最后一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>掠夺两段：一期定价（或产品引入）在「对手留下」的反事实里不是利润最大；二期若对手退出，利润升高，贴现后补回。芝加哥：在位份额更大，亏得更狠；对手可关门等待或融资；事后加价招来新进入——补偿不可信。缺口是哪些摩擦让补偿可信：资本市场不完美、多市场竞争的声誉、网络预期。排他不必低于成本：独家、不兼容、拒绝互联，直接改进入博弈的第二阶段利润或第一阶段 \\(F\\)。</p><p>合并模拟假设 \\(N\\) 外生或只在事后进入；掠夺与排他把 \\(N\\) 当成策略对象。两套反事实不要混成一句「反竞争」。</p><h3 id="低价不等于掠夺" tabindex="-1">低价不等于掠夺 <a class="header-anchor" href="#低价不等于掠夺" aria-label="Permalink to &quot;低价不等于掠夺&quot;">​</a></h3><p>学习曲线、促销、双边补贴都可以把当期价格压到会计成本以下，而不需要对手退出。Ordover–Willig 的检验是反事实利润：若对手被禁止退出，该行为是否仍最优。Areeda–Turner 用短期 AVC 当法律安全港，是近似，不是定义。平台一边免费，上一课已经排除「免费即掠夺」。</p><p><span class="marginnote">反事实检验翻成大白话：把对手强行按在场上不许走，再看这个价格还赚不赚。对手活着也划算，就只是竞争；只有对手死了才划算，才叫掠夺。判断点在牺牲那一期，不在事后加价那一期。</span></p><p><span class="marginnote">McGee 读标准石油：收购往往比亏本销售更便宜。这句话打的是「掠夺是常用工具」的叙事，并不证明均衡里掠夺不存在。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>完全信息单市场：逆向归纳下补偿失败，一期不牺牲。要让掠夺成立，加融资约束（对手亏不起、在位亏得起）、或声誉（这个市场的亏是给其他市场看的信号）。排他：计算对手在被挡住渠道 / 接口之后的进入后利润，是否仍覆盖沉没。网络：拒绝兼容等于强迫自建 \\(n\\)，与抬 \\(F\\) 同构。经验：用事件或结构看「对手退出后加价是否发生」；没有补偿段，牺牲叙事不完整。</p>',12)),(r(),l(i,null,{default:E(()=>[B(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MER%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E6%94%B9%E6%89%80%E6%9C%89%E6%9D%83%22%5D%20--%3E%20STR%5B%22%E6%9C%AC%E8%AF%BE%3A%20%E6%94%B9%E8%B0%81%E5%9C%A8%E5%9C%BA%22%5D%0A%20%20STR%20--%3E%20PRED%5B%22%E6%8E%A0%E5%A4%BA%3A%20%E7%89%BA%E7%89%B2%E5%8A%A0%E8%A1%A5%E5%81%BF%22%5D%0A%20%20STR%20--%3E%20EXCL%5B%22%E6%8E%92%E4%BB%96%3A%20%E6%8A%AC%E9%AB%98%20F%20%E6%88%96%E6%8C%A1%E5%88%A9%E6%B6%A6%22%5D%0A%20%20PRED%20--%3E%20PF%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E5%85%AC%E5%85%B1%E5%93%81%E4%B8%8E%E8%B4%A2%E6%94%BF%22%5D%0A%20%20EXCL%20--%3E%20PF%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"不要把占优厂商的日常低价当成结构证据。势力可以来自成本或网络，低价可以是竞争。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"共同机制是动态互补：今天的行为通过 \\(N\\) 或 \\(n^e\\) 改变明天的需求与成本。掠夺走价格路径；排他走合同与接口；限制进入定价走进入前信号——时序不同，结构目标相同。融资摩擦使「谁更能烧钱」进入支付矩阵，完全市场把这张牌拿走。多市场把一次亏写成声誉投资，单市场模型看不见。",-1)),(r(),l(i,null,{default:E(()=>[B(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SAC%5B%22%E4%B8%80%E6%9C%9F%E7%89%BA%E7%89%B2%3A%20%E4%BB%B7%E6%A0%BC%E4%BD%8E%E4%BA%8E%E5%8F%8D%E4%BA%8B%E5%AE%9E%E6%9C%80%E4%BC%98%22%5D%20--%3E%20Q%7B%22%E5%AF%B9%E6%89%8B%E9%80%80%E5%87%BA%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20BACK%5B%22%E7%89%BA%E7%89%B2%E6%B2%89%E6%B2%A1%3A%20%E6%B2%A1%E6%9C%89%E8%A1%A5%E5%81%BF%E6%AE%B5%22%5D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20REC%5B%22%E4%BA%8C%E6%9C%9F%E5%8A%A0%E4%BB%B7%3A%20N%20%E5%87%8F%E4%B8%80%E5%90%8E%E5%8B%92%E7%BA%B3%E4%B8%8A%E5%8D%87%22%5D%0A%20%20REC%20--%3E%20FC%5B%22%E8%9E%8D%E8%B5%84%E7%BA%A6%E6%9D%9F%3A%20%E5%AF%B9%E6%89%8B%E6%92%91%E4%B8%8D%E4%BD%8F%E7%83%A7%E9%92%B1%22%5D%0A%20%20REC%20--%3E%20REP%5B%22%E5%A4%9A%E5%B8%82%E5%9C%BA%E5%A3%B0%E8%AA%89%3A%20%E4%BA%8F%E7%BB%99%E5%85%B6%E4%BB%96%E5%B8%82%E5%9C%BA%E7%9C%8B%22%5D%0A%20%20REC%20--%3E%20NET%5B%22%E7%BD%91%E7%BB%9C%E9%A2%84%E6%9C%9F%3A%20%E9%80%80%E5%87%BA%E8%80%85%E9%9A%BE%E5%9B%9E%E5%A4%B4%22%5D%0A%20%20FC%20--%3E%20EQ%5B%22%E8%A1%A5%E5%81%BF%E5%8F%AF%E4%BF%A1%3A%20%E6%8E%A0%E5%A4%BA%E5%9D%87%E8%A1%A1%E6%88%90%E7%AB%8B%22%5D%0A%20%20REP%20--%3E%20EQ%0A%20%20NET%20--%3E%20EQ%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p>与合并对照：合并立刻改 \\(\\mathcal{H}\\)，受申报约束；掠夺与排他改 \\(N\\)，更难用事前模拟钉死，因为反事实路径更长。这是 IO 收束时留给公共财政的分界：市场失败若来自封锁，工具是竞争政策；若来自非排他的公共品，工具换税与支出。</p><p><span class="marginnote">「排他抬 \\(F\\)」的直觉类比：狠的不是把独木桥拆掉，而是让对岸只剩自己的渡口——对手想过河得先自建一条船。沉没还没开工，账就已经算不过来了；这就是拒绝兼容与独家渠道在干的事。</span></p><p><span class="marginnote">Ordover–Saloner–Salop 把提高对手成本写成一般策略。纵向排他、标准封闭、掠夺性产品引入，都是同一导数的不同控制变量。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写起诉要件，不提供「如何定价才不算掠夺」的操作清单。不重推微观课已写的 Areeda–Turner 代数。</p><p><span class="marginnote">常见误区：看到「对手退出后价格上升」就喊掠夺。补偿段确实要加价，但退出也可能只是低效对手被自然筛选掉——所以检验要压回牺牲那一期：对手不被赶走时，这价格是否仍最优。只盯补偿段，会把优胜劣汰误判成封锁。</span>量化栏没有对应的「掠夺交易策略」要写。产业组织在此结束：后课默认读者会用需求矩阵、沉没、网络与所有权读结构；本课序的加深层从<a href="/econ/rnd-patent-races">研发竞赛与专利</a>转入创新与纵向；财政侧的<a href="/econ/public-goods-free-rider">公共品自愿供给失败</a>把失败从市场结构换成非排他消费。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>掠夺是改变 \\(N\\) 才最优的牺牲；低价本身不是定义。</li><li>排他通过渠道、接口与沉没封锁进入，不必低于成本。</li><li>完全资本市场、单市场下补偿往往不可信；摩擦把它打开。</li><li>合并改所有权，掠夺与排他改谁在场，反事实更长。</li><li>IO 收束于此；下一块是公共品与税。</li><li>出处：McGee 1958；Ordover and Willig 1981；Ordover, Saloner and Salop；Tirole。</li></ul>',8))])}const T=t(p,[["render",c]]);export{F as __pageData,T as default};
